function enterInterior(site){clearGround();exitBuild();for(const f of fallen)scene.remove(f.g);fallen.length=0;const ret=entrance(site),snapshot=scene.children.filter(o=>o!==actor.root&&o!==hemi&&o!==sun&&o!==sun.target).map(o=>[o,o.visible]);for(const [o] of snapshot)scene.remove(o);const outerW=wolves.splice(0),outerLoot=loot.splice(0);insideInstance=makeInterior(T,scene,visuals,site);renderer.shadowMap.enabled=false;environment.invalidate();enchanted.invalidate();environment.root.visible=false;Object.assign(insideInstance,{snapshot,outerW,outerLoot,returnPos:{...ret,z:ret.z+.65,yaw:0},visited:new Set((s.interiorExplored[site.id]||[]).filter(k=>insideInstance.layout.map.has(k)))});s.x=0;s.z=0;s.yaw=camYaw=camHeadingTarget=0;bodyHeadingTarget=null;camPitch=camPitchTarget=.19;bodyTurnVelocity=0;velocityX=velocityZ=0;cameraFocus=cameraRadius=cameraLift=null;jumpY=jumpV=moveSpeed=0;actor.root.position.set(0,0,0);camera.position.set(0,2.4,-2.2);if(site.reward&&!s.opened[site.id]){const t=insideInstance.treasure;chest(t.x,t.z,site.id,true);for(const [i,pos] of insideInstance.guards.entries()){const id='guard:'+site.id+':'+i;if(s.opened[id])continue;const w=creature(pos.x,pos.z,site.guard);w.site=site.id;w.guardId=id;w.maxHp=w.hp=i===insideInstance.guards.length-1?85:55;wolves.push(w)}}s.opened['discover:'+site.id]=true;insideInstance.visited.add('0,0');visitInterior(s,site.id,'0,0');insideInstance.update(0,0,0);syncGround();save()}
