function witchTrade(){if(s.opened['witch-remedy']){toast('La strega: che gli antenati ti proteggano.');return}if(!has(s,{mushroom:3,reed:4})){toast('La strega: portami 3 funghi e 4 giunchi.');return}take(s,'mushroom',3);take(s,'reed',4);add(s,'food',3);add(s,'venom',2);s.health=100;s.opened['witch-remedy']=true;toast('Rimedio della strega: salute ripristinata, cibo ed essenza.');updateHud();save()}
function interact(){if(state!=='play'||paletteOpen()||terrainActive||building)return;const grave=graveNear();if(grave){if(recoverGrave(s,grave.id,currentArea(),s.x,s.z)){syncGraves();updateHud();save();toast('Inventario recuperato')}return}const portal=portalNear();if(portal){requestTravel(portal);return}if(witchNear()){witchTrade();return}const hit=aimedTarget();if(hit?.valid&&hit.target.kind==='chest'){useChest(hit.target);return}const structure=nearStructure(),fire=fireNear();if(fire&&(!structure||Math.hypot(s.x-fire.x,s.z-fire.z)<Math.hypot(s.x-structure.x,s.z-structure.z))){openCooking(fire);return}if(structure){structureUse(structure);return}const chestNearby=loot.find(r=>r.g.visible&&Math.hypot(s.x-r.x,s.z-r.z)<2.15);if(chestNearby){useChest(chestNearby);return}if(!insideInstance&&waterDist(s.x,s.z)<22){drink(s);toast('Hai bevuto acqua.');return}toast('Avvicinati e rivolgiti alla risorsa.')}
function foodAction(){if(state!=='play')return;const id=s.hotbar[s.selected];if((['food','bearfood','berries','mushroom','cactus'].includes(id)&&eat(s,id))||eat(s,'food')||eat(s,'bearfood')||eat(s,'berries')||eat(s,'mushroom')||eat(s,'cactus')){toast('Hai mangiato.');updateHud();save()}else toast('Non hai cibo nello zaino.')}
