function attack(){if(state!=='play'||paletteOpen()||terrainActive||building||attackCooldown>0||parryAge<PARRY_WINDOW||s.stamina<4)return;attackYaw=camYaw;bodyHeadingTarget=attackYaw;attackCooldown=.66;attackTime=.48;attackPending={at:.22,weapon:s.equipped.weapon};s.stamina=clamp(s.stamina-(s.equipped.weapon?4:2))}
function packedSelected(){return ['sapling','bench','campfire','well','chest','wardrobe','hoe'].includes(s.hotbar[s.selected])&&!!s.inventory[s.hotbar[s.selected]]}
function canParry(){return !packedSelected()&&state==='play'&&s.equipped.shield&&s.inventory.shield&&!building&&!terrainActive&&!paletteOpen()&&s.equipped.weapon!=='hammer'}
function tryParry(){if(!canParry()||parryCooldown>0||attackPending||s.stamina<8)return false;parryAge=0;parryCooldown=PARRY_COOLDOWN;parryYaw=camYaw;bodyHeadingTarget=parryYaw;s.stamina=clamp(s.stamina-8);guardPose=1;return true}
function combatTick(dt){parryAge+=dt;parryCooldown=Math.max(0,parryCooldown-dt);guardPose+=( (parryAge<PARRY_WINDOW?1:0)-guardPose)*smoothFactor(20,dt);if(!canParry()){guardPose=0;parryAge=10}if(attackPending){attackPending.at-=dt;if(attackPending.at<=0){const p=attackPending;attackPending=null;if(p.weapon===s.equipped.weapon){const hit=aimedTarget(attackYaw);if(hit?.valid)hitTarget(hit);else combatNotice('A vuoto','miss')}}}combatFeedback-=dt;if(combatFeedback<=0)$('combat-feedback').hidden=true;$('shield-status').hidden=!canParry();if(canParry()){$('shield-status').textContent=parryAge<PARRY_WINDOW?'PARATA ATTIVA':parryCooldown>0?'SCUDO IN RECUPERO':'SCUDO PRONTO · '+(touchDevice?'TOCCA':'DESTRO');$('shield-status').dataset.ready=String(parryCooldown<=0)}}

function placeAction(){if(state!=='play')return;if(paletteOpen()){closeBuildMenu();return}if(terrainActive){applyTerrain();return}if(building){placeBuild();return}const id=s.hotbar[s.selected];if(id==='sapling'&&s.inventory[id]){beginSaplingPlacement();return}if(id==='bench'&&s.inventory[id]){beginBenchPlacement();return}if(id==='campfire'&&s.inventory[id]){beginFirePlacement();return}if(id==='well'&&s.inventory[id]){beginWellPlacement();return}if(['chest','wardrobe'].includes(id)&&s.inventory[id]){beginChestPlacement(id);return}if(id==='hoe'&&s.inventory[id]){enterTerrain();return}if(s.equipped.weapon==='hammer')openBuildMenu();else tryParry()}
