 w.hit=Math.max(0,w.hit-dt);w.recover=Math.max(0,(w.recover||0)-dt);const dx=s.x-w.x,dz=s.z-w.z,d=Math.hypot(dx,dz),passive=passiveKinds.includes(w.kind),profile=enemyAttackProfile(w.kind);w.g.visible=d<90;if(d>100){clearStrike(w);continue}
